import pytest
from matchescu.reference_store.id_table import InMemoryIdTable
from matchescu.typing import EntityReference, EntityReferenceIdentifier

# labels 1 and 2 are taken by the existing references, so the bridge
# generated by AmbiguityGenerator receives max(label) + 1
BRIDGE_LABEL = 3


@pytest.fixture
def home_ref_id():
    return EntityReferenceIdentifier(1, "home")


@pytest.fixture
def prox_ref_id():
    return EntityReferenceIdentifier(2, "prox")


@pytest.fixture
def bridge_ref_id():
    return EntityReferenceIdentifier(BRIDGE_LABEL, "ambiguity-generator")


@pytest.fixture
def home_ref(home_ref_id):
    return EntityReference(
        home_ref_id, {"name": "John Doe", "year": "1990", "city": "X"}
    )


@pytest.fixture
def prox_ref(prox_ref_id):
    return EntityReference(
        prox_ref_id, {"name": "Jane Doe", "year": "2000", "city": "Y"}
    )


@pytest.fixture
def id_table(home_ref, prox_ref):
    return InMemoryIdTable().put(home_ref).put(prox_ref)


@pytest.fixture
def clusters(home_ref_id, prox_ref_id):
    return frozenset({frozenset({home_ref_id}), frozenset({prox_ref_id})})


@pytest.fixture
def make_table(home_ref_id, prox_ref_id):
    def _make(home_properties, proximal_properties):
        home_ref = EntityReference(home_ref_id, home_properties)
        prox_ref = EntityReference(prox_ref_id, proximal_properties)
        id_table = InMemoryIdTable().put(home_ref).put(prox_ref)
        return home_ref, prox_ref, id_table

    return _make
